public class Solution {
    public static int[] solve(int[] readyDays) {
        Queue<Integer> waiting = new ArrayDeque<>();
        for (int day : readyDays) waiting.add(day);
        List<Integer> batches = new ArrayList<>();
        while (!waiting.isEmpty()) {
            int releaseDay = waiting.remove();
            int count = 1;
            while (!waiting.isEmpty() && waiting.peek() <= releaseDay) {
                waiting.remove();
                count++;
            }
            batches.add(count);
        }
        return batches.stream().mapToInt(Integer::intValue).toArray();
    }
}

