        Deque<Integer> deque = new ArrayDeque<>();
        List<Integer> removed = new ArrayList<>();
        for (int[] command : commands) {
            int type = command[0];
            if (type == 1) deque.addFirst(command[1]);
            else if (type == 2) deque.addLast(command[1]);
            else if (type == 3) removed.add(deque.isEmpty() ? -1 : deque.removeFirst());
            else removed.add(deque.isEmpty() ? -1 : deque.removeLast());
        }
        return removed.stream().mapToInt(Integer::intValue).toArray();
    }
}

