import java.util.*;

public class Solution {
    public static int solve(int[] priorities, int targetIndex) {
        Queue<Integer> waiting = new ArrayDeque<>();
        PriorityQueue<Integer> remaining = new PriorityQueue<>(Comparator.reverseOrder());
        for (int index = 0; index < priorities.length; index++) {
            waiting.add(index);
            remaining.add(priorities[index]);
        }
        int order = 0;
        while (!waiting.isEmpty()) {
            int current = waiting.remove();
            if (priorities[current] < remaining.peek()) {
                waiting.add(current);
                continue;
            }
            remaining.remove();
            order++;
            if (current == targetIndex) return order;
        }
        return order;
    }
}

